<script setup lang="ts">
import {ref} from 'vue'
import {useRouter} from 'vue-router'
import Icon from '../components/Icon.vue'
import {state,t,api,loadWorkspaces,loadData,notify} from '../state'
const router=useRouter(),busy=ref(false)
async function open(){if(state.user&&state.workspace?.onboarded){router.push('/overview');return}busy.value=true;try{const r=await api('/demo',{method:'POST',body:{variant:'industrial'}});state.user=r.user;await loadWorkspaces(r.workspace_id);await loadData();router.push('/overview')}catch(e:any){notify(e.message,true)}finally{busy.value=false}}
</script>
<template><div class="bank-preview-app"><header><div class="row gap-sm"><span class="bank-mark">A</span><strong>{{t('Alfa-Business','Альфа-Бизнес')}}</strong><span class="badge neutral">{{t('Integration prototype','Прототип интеграции')}}</span></div><span class="small muted">{{t('Demonstration · no bank account is connected','Демонстрация · банковский счёт не подключён')}}</span></header><div class="bank-preview-layout"><aside><h4>{{t('Volga Industrial Group','Volga Industrial Group')}}</h4><span v-for="n in [t('Business overview','Обзор бизнеса'),t('Accounts & payments','Счета и платежи'),t('Financing','Финансирование'),t('Services','Сервисы')]" :key="n">{{n}}</span><button @click="open" :disabled="busy"><Icon name="Radar" :size="18"/>{{t('Business signals','Бизнес-сигналы')}}<span class="count-pill">4</span></button><p>{{t('This page demonstrates a persistent analytics entry point inside an internet bank.','Эта страница показывает постоянную точку входа в аналитику внутри интернет-банка.')}}</p></aside><main><span class="eyebrow">{{t('YOUR BUSINESS AT A GLANCE','ВАШ БИЗНЕС В ОБЗОРЕ')}}</span><h1>{{t('Good decisions start here.','Здесь начинаются обоснованные решения.')}}</h1><div class="notice"><Icon name="FlaskConical" :size="18"/>{{t('An illustrative bank shell for the case demonstration. Company and event data are synthetic. No payment actions are available.','Учебный интерфейс банка для демонстрации кейса. Данные компании и событий синтетические. Платёжные операции недоступны.')}}</div><section class="bank-entry-card"><div class="row between"><span class="eyebrow">{{t('NEWS & BUSINESS INTELLIGENCE','НОВОСТНАЯ БИЗНЕС-АНАЛИТИКА')}}</span><Icon name="Radar" :size="30"/></div><h2>{{t('What’s changing for your business?','Что меняется для вашего бизнеса?')}}</h2><p>{{t('Signals selected for your company, with Alfa-Bank research, business impact and a useful next move.','События, отобранные для вашей компании: аналитика Альфа-Банка, влияние на бизнес и полезный следующий шаг.')}}</p><div class="bank-preview-signals"><div><span class="badge risk">{{t('Financing','Финансирование')}}</span><strong>{{t('A closer look at your next refinancing window','Оцените ближайшее окно рефинансирования')}}</strong><span>{{t('Your credit exposure links this signal to cash-flow planning.','Кредитные обязательства связывают этот сигнал с планированием денежного потока.')}}</span></div><div><span class="badge opportunity">{{t('Supply chain','Цепочки поставок')}}</span><strong>{{t('A new route to a more resilient supply chain','Новый путь к устойчивым поставкам')}}</strong><span>{{t('Additional supplier capacity is worth validating against your cost base.','Новые мощности поставщика стоит сопоставить с вашей структурой затрат.')}}</span></div></div><button class="btn primary large-btn" @click="open" :disabled="busy"><Icon :name="busy?'LoaderCircle':'ArrowUpRight'" :class="{spin:busy}" :size="18"/>{{t('Open business intelligence','Открыть бизнес-аналитику')}}</button><span class="small muted">{{t('Powered by SignalDesk','На основе SignalDesk')}}</span></section></main></div></div></template>
